   944  M3Result  m3_GetResultsVL  (IM3Function i_function, va_list o_rets)
   945  {
   946      IM3Runtime runtime = i_function->module->runtime;
   947      IM3FuncType ftype = i_function->funcType;
   948
   949      if (i_function != runtime->lastCalled) {
   950          return "function not called";
   951      }
   952
   953      u8* s = (u8*) runtime->stack;
   954      for (u32 i = 0; i < ftype->numRets; ++i)
   955      {
   956          switch (d_FuncRetType(ftype, i)) {
   957          case c_m3Type_i32:  *va_arg(o_rets, i32*) = *(i32*)(s);  s += 4; break;
   958          case c_m3Type_i64:  s = AlignStackPointerTo64Bits (s); *va_arg(o_rets, i64*) = *(i64*)(s);  s += 8; break;
   959          case c_m3Type_f32:  *va_arg(o_rets, f32*) = *(f32*)(s);  s += 4; break;
   960          case c_m3Type_f64:  s = AlignStackPointerTo64Bits (s); *va_arg(o_rets, f64*) = *(f64*)(s);  s += 8; break;
   961          default: return "unknown argument type";
   962          }
   963      }
   964      return m3Err_none;
