    49  M3Result  EmitOp  (IM3Compilation o, IM3Operation i_operation)
    50  {
    51      M3Result result = m3Err_none;                                 d_m3Assert (i_operation or IsStackPolymorphic(o));
    52
    53      // it's OK for page to be null; when compile-walking the bytecode without emitting
    54      if (o->page)
    55      {
    56  # if d_m3EnableOpTracing
    57          if (i_operation != op_DumpStack)
    58  # endif
    59              o->numEmits++;
    60
    61          result = BridgeToNewPageIfNecessary (o);
    62
    63          if (not result)
    64          {                                                           if (d_m3LogEmit) log_emit (o, i_operation);
    65  # if d_m3RecordBacktraces
    66              EmitMappingEntry (o->page, o->lastOpcodeStart - o->module->wasmStart);
    67  # endif // d_m3RecordBacktraces
    68              EmitWord (o->page, i_operation);
    69          }
    70      }
    71
    72      return result;
    73  }
