   779  M3Result  m3_CallVL  (IM3Function i_function, va_list i_args)
   780  {
   781      IM3Runtime runtime = i_function->module->runtime;
   782      IM3FuncType ftype = i_function->funcType;
   783
   784      if (!i_function->compiled) {
   785          return m3Err_missingCompiledCode;
   786      }
   787
   788  # if d_m3RecordBacktraces
   789      ClearBacktrace (runtime);
   790  # endif
   791
   792      u8* s = GetStackPointerForArgs (i_function);
   793
   794      for (u32 i = 0; i < ftype->numArgs; ++i)
   795      {
   796          switch (d_FuncArgType(ftype, i)) {
   797          case c_m3Type_i32:  *(i32*)(s) = va_arg(i_args, i32);  s += 8; break;
   798          case c_m3Type_i64:  *(i64*)(s) = va_arg(i_args, i64);  s += 8; break;
   799          case c_m3Type_f32:  *(f32*)(s) = va_arg(i_args, f64);  s += 8; break; // f32 is passed as f64
   800          case c_m3Type_f64:  *(f64*)(s) = va_arg(i_args, f64);  s += 8; break;
   801          default: return "unknown argument type";
   802          }
   803      }
   804      m3StackCheckInit();
   805      M3Result r = (M3Result) Call (i_function->compiled, (m3stack_t)(runtime->stack), runtime->memory.mallocated, d_m3OpDefaultArgs);
   806
   807      runtime->lastCalled = r ? NULL : i_function;
   808
   809  #if d_m3LogNativeStack
   810      int stackUsed =  m3StackGetMax();
   811      fprintf (stderr, "Native stack used: %d\n", stackUsed);
   812  #endif
   813
   814      return r;
   815  }
